// A self-contained five-second H.264 Constrained Baseline still with a silent AAC-LC stereo
// track. Keeping it in the Worker avoids an external dependency and supports Fire TV playback.
const BASE64 = "";

let cached: ArrayBuffer | undefined;

function bytes(): ArrayBuffer {
  if (cached) return cached;
  const binary = atob(BASE64);
  cached = Uint8Array.from(binary, (character) => character.charCodeAt(0)).buffer;
  return cached;
}

function shortChannelVideo(request: Request, filename: string, etag: string): Response {
  const body = bytes();
  const headers = new Headers({
    "accept-ranges": "bytes",
    "access-control-allow-origin": "*",
    "cache-control": "public, max-age=86400, immutable",
    "content-disposition": `inline; filename="${filename}"`,
    "content-type": "video/mp4",
    etag,
  });
  const rangeHeader = request.headers.get("range");
  if (!rangeHeader) {
    headers.set("content-length", String(body.byteLength));
    if (request.headers.get("if-none-match") === headers.get("etag")) return new Response(null, { status: 304, headers });
    return new Response(request.method === "HEAD" ? null : body, { headers });
  }

  const range = rangeHeader.match(/^bytes=(\d*)-(\d*)$/);
  if (!range || (!range[1] && !range[2])) {
    headers.set("content-range", `bytes */${body.byteLength}`);
    return new Response(null, { status: 416, headers });
  }
  const suffixLength = !range[1] && range[2] ? Number(range[2]) : null;
  const start = suffixLength === null ? Number(range[1]) : Math.max(0, body.byteLength - suffixLength);
  const requestedEnd = suffixLength === null && range[2] ? Number(range[2]) : body.byteLength - 1;
  const end = Math.min(requestedEnd, body.byteLength - 1);
  if (!Number.isInteger(start) || !Number.isInteger(end) || start < 0 || start >= body.byteLength || end < start) {
    headers.set("content-range", `bytes */${body.byteLength}`);
    return new Response(null, { status: 416, headers });
  }
  const part = body.slice(start, end + 1);
  headers.set("content-length", String(part.byteLength));
  headers.set("content-range", `bytes ${start}-${end}/${body.byteLength}`);
  return new Response(request.method === "HEAD" ? null : part, { status: 206, headers });
}

export function movieSignOff(request: Request): Response {
  return shortChannelVideo(request, "kids-channels-sign-off.mp4", "\"kids-channels-sign-off-v2\"");
}

export async function programmeUnavailable(request: Request, assets?: Fetcher): Promise<Response> {
  if (assets) {
    const assetUrl = new URL(request.url);
    assetUrl.pathname = "/programme-unavailable.mp4";
    const response = await assets.fetch(new Request(assetUrl, request));
    if (response.ok) {
      const headers = new Headers(response.headers);
      headers.set("accept-ranges", "bytes");
      headers.set("access-control-allow-origin", "*");
      headers.set("cache-control", "public, max-age=86400, immutable");
      headers.set("content-disposition", "inline; filename=\"kids-channels-programme-unavailable.mp4\"");
      headers.set("content-type", "video/mp4");
      return new Response(response.body, { status: response.status, headers });
    }
  }
  return shortChannelVideo(
    request,
    "kids-channels-programme-unavailable.mp4",
    "\"kids-channels-programme-unavailable-v2\"",
  );
}
